<?php
require_once 'config.php';requirePost();$user=requireLogin();if($user['role']==='supervisor'&&!hasPermission('can_chat'))jsonResponse(['success'=>false,'message'=>'دسترسی چت غیرفعال است.'],403);$conv=postInt('conversation_id');$rawBody=(string)($_POST['body']??'');$body=(str_starts_with($rawBody,'[voice]')||str_starts_with($rawBody,'[webrtc-'))?normalizeText($rawBody,60000):normalizeText($rawBody,2000);if($conv<1||$body==='')jsonResponse(['success'=>false,'message'=>'پیام خالی است.'],400);if(!canAccessChatConversation($pdo,$conv,$user['role'],$user['username']))jsonResponse(['success'=>false,'message'=>'دسترسی غیرمجاز.'],403);$st=$pdo->prepare("INSERT INTO chat_messages(conversation_id,sender_username,sender_role,sender_name,body) VALUES(?,?,?,?,?)");$st->execute([$conv,$user['username'],$user['role'],$user['display_name'],$body]);jsonResponse(['success'=>true,'id'=>(int)$pdo->lastInsertId()]);
